package com.aistock.scheduler.alert;
import static com.aistock.scheduler.alert.AlertMarketClient.*;import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;
@Tag("mysql") class AlertScanMysqlTest {
 AlertJobMysqlTest f;AlertScanRepository scans;AlertJobRepository jobs;AlertJobMysqlTest.TestClock clock;
 @BeforeEach void setup(){f=new AlertJobMysqlTest();f.setup();jobs=f.jobs;clock=f.clock;f.jdbc.update("delete from alert_scan_cursor");f.jdbc.update("delete from alert_calendar_refresh");scans=new AlertScanRepository(f.jdbc,jobs,60,1000,20);}
 com.aistock.scheduler.task.RevisionClient.Event event(long id){return new com.aistock.scheduler.task.RevisionClient.Event(id,"SH600030",UUID.randomUUID().toString());}
 RuleRef rule(String id){return new RuleRef(UUID.fromString(id),UUID.randomUUID(),"SH600030",0,LocalDate.of(2026,10,8));}
 AlertScanRepository.Cursor started(String kind){var c=scans.cursor(kind,clock.instant());assertTrue(scans.begin(c,kind.equals("EVENT")?event(1):null,LocalDate.of(2026,10,9),LocalDate.of(2026,10,9),clock.instant()));return scans.cursor(kind,clock.instant());}
 AlertJobRecords.Input input(AlertScanRepository.Cursor c,RuleRef r){return new AlertJobRecords.Input(r.ruleId(),r.revision(),r.instrumentId(),c.expectedDate(),UUID.randomUUID(),c.roundId());}
 @Test void pageAndJobsCommitAtomicallyAndOldCursorCannotRepublish(){var c=started("EVENT");var r=rule("11111111-1111-1111-1111-111111111111");var page=new Page(List.of(r),r.ruleId().toString());assertTrue(scans.publish(c,page,List.of(input(c,r)),clock.instant(),null));assertFalse(scans.publish(c,page,List.of(input(c,r)),clock.instant(),null));assertEquals(1,f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));assertEquals(r.ruleId().toString(),scans.cursor("EVENT",clock.instant()).afterId());assertEquals(0,scans.cursor("RECONCILE",clock.instant()).completedEventId());}
 @Test void badJobRollsBackCursorAndEntirePage(){var c=started("EVENT");var a=rule("11111111-1111-1111-1111-111111111111");var b=rule("22222222-2222-2222-2222-222222222222");var bad=new AlertJobRecords.Input(b.ruleId(),0,"SH600030",c.expectedDate(),null,c.roundId());assertThrows(RuntimeException.class,()->scans.publish(c,new Page(List.of(a,b),null),List.of(input(c,a),bad),clock.instant(),null));assertEquals(c,scans.cursor("EVENT",clock.instant()));assertEquals(0,f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));}
 @Test void failedSecondPageKeepsSavedPositionAndRestartResumes(){var c=started("EVENT");var r=rule("11111111-1111-1111-1111-111111111111");scans.publish(c,new Page(List.of(r),r.ruleId().toString()),List.of(),clock.instant(),null);var saved=scans.cursor("EVENT",clock.instant());scans.defer(saved,"ALERT_PAGE_UNAVAILABLE",clock.instant());scans=new AlertScanRepository(f.jdbc,jobs,60,1000,20);assertEquals(saved.afterId(),scans.cursor("EVENT",clock.instant()).afterId());assertEquals(saved.roundId(),scans.cursor("EVENT",clock.instant()).roundId());assertEquals(0,scans.cursor("EVENT",clock.instant()).completedEventId());}
 @Test void completedReconcileWaitsOneHourAndNewRoundRestartsPagination(){var c=started("RECONCILE");assertTrue(scans.publish(c,new Page(List.of(),null),List.of(),clock.instant(),null));var finished=scans.cursor("RECONCILE",clock.instant());assertNull(finished.roundId());assertFalse(scans.begin(finished,null,c.cutoffDate(),c.expectedDate(),clock.instant()));clock.advance(3600);assertTrue(scans.begin(scans.cursor("RECONCILE",clock.instant()),null,c.cutoffDate(),c.expectedDate(),clock.instant()));assertNull(scans.cursor("RECONCILE",clock.instant()).afterId());}
 @Test void cutoffChangeRejectsOldPageAndResetsRound(){var c=started("EVENT");clock.advance(14400);assertFalse(scans.publish(c,new Page(List.of(),null),List.of(),clock.instant(),null));assertTrue(scans.begin(scans.cursor("EVENT",clock.instant()),new com.aistock.scheduler.task.RevisionClient.Event(c.eventId(),c.instrumentId(),c.eventRawVersion()),LocalDate.of(2026,10,10),LocalDate.of(2026,10,9),clock.instant()));assertNotEquals(c.roundId(),scans.cursor("EVENT",clock.instant()).roundId());}
 @Test void calendarRefreshIsLeasedDailyAndFailureRetriesSameOperationAfterFiveMinutes(){var c=scans.claimCalendar(clock.instant());assertNotNull(c);assertNull(scans.claimCalendar(clock.instant()));assertEquals(LocalDate.of(2025,10,9),c.start());assertEquals(LocalDate.of(2026,10,10),c.end());assertTrue(scans.finishCalendar(c,false,"CALENDAR_SOURCE_UNAVAILABLE",clock.instant()));assertNull(scans.claimCalendar(clock.instant()));clock.advance(300);var retry=scans.claimCalendar(clock.instant());assertEquals(c.operationId(),retry.operationId());assertNotEquals(c.owner(),retry.owner());assertFalse(scans.finishCalendar(c,true,null,clock.instant()));assertTrue(scans.finishCalendar(retry,true,null,clock.instant()));clock.advance(3600);assertNull(scans.claimCalendar(clock.instant()));}
 @Test void competingPublishersCommitOnlyOnePage()throws Exception{var c=started("EVENT");var r=rule("11111111-1111-1111-1111-111111111111");var page=new Page(List.of(r),null);var input=input(c,r);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(List.<java.util.concurrent.Callable<Boolean>>of(()->scans.publish(c,page,List.of(input),clock.instant(),null),()->scans.publish(c,page,List.of(input),clock.instant(),null)));int winners=0;for(var result:results)if(result.get())winners++;assertEquals(1,winners);assertEquals(1,f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));}finally{pool.shutdownNow();}}
 @Test void fullQueueDoesNotAdvanceCursor(){scans=new AlertScanRepository(f.jdbc,jobs,60,1,20);var c=started("EVENT");f.enqueue();var r=rule("11111111-1111-1111-1111-111111111111");assertFalse(scans.publish(c,new Page(List.of(r),null),List.of(input(c,r)),clock.instant(),null));assertEquals(c,scans.cursor("EVENT",clock.instant()));}
}
